# Sort by descending length to remove the _longest_ match.
# E.g. remove "señorita" and not "señor", when both match.
HONORIFICS: Final = sorted(
    [
        'countess',
        'doctor',
        'doktor',
        'dr',
        'dr.',
        'frau',
        'fräulein',
        'herr',
        'lady',
        'lord',
        'm.',
        'madame',
        'mademoiselle',
        'miss',
        'mister',
        'mistress',
        'mixter',
        'mlle',
